// Expand a recurring calendar event into the dates it occurs on.
//
// A date is a string "YYYY-MM-DD": exactly four digits, '-', two digits, '-', two digits,
// naming a real day of the Gregorian calendar with year 0001 to 9999 (a leap year is
// divisible by 4, except that a year divisible by 100 must also be divisible by 400).
// freq is "daily", "weekly", "monthly" or "yearly", and interval >= 1 is the step:
// candidate k (k = 0, 1, 2, ...) is start plus k * interval days, weeks, months or
// years, so candidate 0 is start itself. A "monthly" or "yearly" candidate keeps start's
// day of the month; when its month has no such day (the 31st of a 30-day month,
// February 29th outside a leap year) the candidate is skipped and does not count.
//
// Return the first count occurrences in date order, stopping before the first one that
// is later than until; until is a date, or "" for no end date. A candidate after year
// 9999 ends the expansion. Return None if start or a non-empty until is not a valid
// date, freq is not one of the four names, interval < 1 or count < 0.
// Examples:
//   expand_recurrence("2024-01-31", "monthly", 1, 4, "") == Some(["2024-01-31", "2024-03-31", "2024-05-31", "2024-07-31"])
//   expand_recurrence("2023-12-30", "weekly", 1, 10, "2024-01-14") == Some(["2023-12-30", "2024-01-06", "2024-01-13"])
fn expand_recurrence(start: Str, freq: Str, interval: Int, count: Int, until: Str) -> Option[List[Str]] {
  let (y0, m0, d0) = parse_date(start)?;
  if interval < 1 || count < 0 {
    return None;
  }
  let step_months = match freq {
    "daily" | "weekly" => 0,
    "monthly" => interval,
    "yearly" => interval * 12,
    _ => { return None; },
  };
  if until != "" {
    parse_date(until)?;
  }
  let step_days = if freq == "weekly" { interval * 7 } else { interval };
  let z0 = days_from_civil(y0, m0, d0);
  let max_day = days_from_civil(9999, 12, 31);
  let mut out: List[Str] = [];
  let mut k = 0;
  while len(out) < count {
    let mut date = (0, 0, 0); // stays at year 0 for a skipped month
    if step_months == 0 {
      let z = z0 + k * step_days;
      if z > max_day {
        break;
      }
      date = civil_from_days(z);
    } else {
      let mi = (m0 - 1) + k * step_months;
      let (y, m) = (y0 + mi / 12, mi % 12 + 1);
      if y > 9999 {
        break;
      }
      if d0 <= days_in_month(y, m) {
        date = (y, m, d0);
      }
    }
    k = k + 1;
    if date.0 > 0 {
      let text = pad(date.0, 4) ++ "-" ++ pad(date.1, 2) ++ "-" ++ pad(date.2, 2);
      // valid dates are zero-padded, so string order is date order
      if until != "" && text > until {
        break;
      }
      out = push(out, text);
    }
  }
  Some(out)
}

fn pad(n: Int, width: Int) -> Str {
  let s = show(n);
  repeat("0", max(0, width - str_len(s))) ++ s
}

fn is_leap(y: Int) -> Bool {
  (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

fn days_in_month(y: Int, m: Int) -> Int {
  if m == 2 { if is_leap(y) { 29 } else { 28 } } else if contains([4, 6, 9, 11], m) { 30 } else { 31 }
}

fn parse_date(s: Str) -> Option[(Int, Int, Int)] {
  let cs = chars(s);
  if len(cs) != 10 || cs[4] != "-" || cs[7] != "-" {
    return None;
  }
  if !all([0, 1, 2, 3, 5, 6, 8, 9], |i| is_digit(cs[i])) {
    return None;
  }
  let y = parse_int(substr(s, 0, 4))?;
  let m = parse_int(substr(s, 5, 7))?;
  let d = parse_int(substr(s, 8, 10))?;
  if y < 1 || m < 1 || m > 12 || d < 1 || d > days_in_month(y, m) {
    return None;
  }
  Some((y, m, d))
}

// days since 1970-01-01 (Howard Hinnant's algorithm, years >= 1)
fn days_from_civil(y0: Int, m: Int, d: Int) -> Int {
  let y = if m <= 2 { y0 - 1 } else { y0 };
  let era = y / 400;
  let yoe = y - era * 400;
  let doy = (153 * (if m > 2 { m - 3 } else { m + 9 }) + 2) / 5 + d - 1;
  let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
  era * 146097 + doe - 719468
}

fn civil_from_days(z0: Int) -> (Int, Int, Int) {
  let z = z0 + 719468;
  let era = z / 146097;
  let doe = z - era * 146097;
  let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
  let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
  let mp = (5 * doy + 2) / 153;
  let d = doy - (153 * mp + 2) / 5 + 1;
  let m = if mp < 10 { mp + 3 } else { mp - 9 };
  (yoe + era * 400 + (if m <= 2 { 1 } else { 0 }), m, d)
}
